import{_t as e,it as t,n,rt as r}from"./chunks/framework.BM2esBXZ.js";var i=JSON.parse(`{"title":"为什么是曦寒","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/why.md","filePath":"appendix/why.md","lastUpdated":1794052435000}`),a={name:`appendix/why.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="为什么是曦寒" tabindex="-1">为什么是曦寒 <a class="header-anchor" href="#为什么是曦寒" aria-label="Permalink to “为什么是曦寒”">​</a></h1><p>.NET 上不缺应用框架。这一页回答两个问题：XiHan Framework 解决了哪些别的框架没解决好的问题，以及为此你要付出什么代价。它是选型说明，适合正在评估后端框架的团队；已经决定使用的读者可以直接去<a href="/getting-started/installation">入门指南</a>。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to “先说结论”">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>建议</th></tr></thead><tbody><tr><td>中大型、长期维护、多人协作的 .NET 后端，重视依赖边界与可替换性</td><td>适合</td></tr><tr><td>多租户 SaaS、企业中后台，需要租户、权限、审计、工作流、调度这类通用能力</td><td>适合</td></tr><tr><td>同一业务要同时提供 REST、gRPC、MCP tool 或命令行</td><td>适合</td></tr><tr><td>需要第三方用其他语言写插件，或要求插件崩溃不拖垮宿主</td><td>适合</td></tr><tr><td>目标是 Native AOT 发布或冷启动敏感的服务</td><td>适合，非 AOT 的 Provider 需替换或接受 JIT</td></tr><tr><td>短期项目，只要几个 CRUD 接口</td><td>直接用 ASP.NET Core 最小 API 更省事</td></tr><tr><td>必须马上上生产、需要正式版</td><td>框架仍是预览版，见本页末尾的「当前限制」</td></tr></tbody></table><h2 id="五个痛点与解法" tabindex="-1">五个痛点与解法 <a class="header-anchor" href="#五个痛点与解法" aria-label="Permalink to “五个痛点与解法”">​</a></h2><h3 id="依赖关系到运行时才知道" tabindex="-1">依赖关系到运行时才知道 <a class="header-anchor" href="#依赖关系到运行时才知道" aria-label="Permalink to “依赖关系到运行时才知道”">​</a></h3><p>多数模块化框架把依赖写在模块特性或基类上，谁依赖谁、缺了什么、版本是否匹配，要跑起来才知道。这里每个特性带一份清单，按能力 ID 声明依赖：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>xihan.persistence.inmemory &lt;版本&gt; (default)</span></span>
<span class="line"><span>  provides persistence.relational@1</span></span>
<span class="line"><span>  requires kernel.hosting@1 -&gt; xihan.kernel.core</span></span></code></pre></div><p>内核在构建期求解全部清单，缺失依赖、循环、版本冲突、同一能力多个候选都会带着双方信息报错；启动日志与 <code>graph</code> 命令打印同一份已解析图。同一能力有多个 Provider 时，选择写在配置里，不靠注册顺序。</p><h3 id="横切逻辑没有固定位置" tabindex="-1">横切逻辑没有固定位置 <a class="header-anchor" href="#横切逻辑没有固定位置" aria-label="Permalink to “横切逻辑没有固定位置”">​</a></h3><p>认证、租户、授权、校验、幂等、事务分别散在过滤器、拦截器、基类虚方法里，顺序靠约定。这里它们落在管道的固定阶段，任何协议进来的调用都经过同一条管道。中间件只关心自己的阶段，顺序由「阶段、约束、归属」确定并可打印，不依赖动态代理。</p><h3 id="一个业务三份胶水" tabindex="-1">一个业务三份胶水 <a class="header-anchor" href="#一个业务三份胶水" aria-label="Permalink to “一个业务三份胶水”">​</a></h3><p>要同时提供 REST、gRPC 与 MCP，通常得写控制器、proto 与 tool 描述三份东西，还要各自维护授权与错误码。这里操作以 <code>[Operation]</code> 声明一次，源生成器产出 JSON Schema。HTTP 路由、OpenAPI 文档、gRPC 的 <code>.proto</code>、MCP 的 tool 描述、命令行参数都由同一份契约推出，授权要求与错误码在各协议上一致。</p><h3 id="开发环境离不开基础设施" tabindex="-1">开发环境离不开基础设施 <a class="header-anchor" href="#开发环境离不开基础设施" aria-label="Permalink to “开发环境离不开基础设施”">​</a></h3><p>很多框架的抽象没有能用的默认实现，本地跑起来要先装数据库、Redis 和消息代理。这里每个子系统的抽象都有一个零外部依赖、容量有界的默认实现。上线时加 Provider 包与一行 <code>UseFeature</code>，默认实现自动让位；Provider 与默认实现通过同一套一致性套件，行为差异在套件里可见。</p><h3 id="架构约束靠人记" tabindex="-1">架构约束靠人记 <a class="header-anchor" href="#架构约束靠人记" aria-label="Permalink to “架构约束靠人记”">​</a></h3><p>依赖方向、命名、分层这些规则写在文档里，靠代码评审记忆，三个月后就松了。这里依赖方向、包 ID 文法、命名空间、零反射、第三方类型泄漏、XML 文档、消息键与语言文件的一致性都由架构测试与分析器执行，违反即 CI 失败。</p><h2 id="与同类框架的对比" tabindex="-1">与同类框架的对比 <a class="header-anchor" href="#与同类框架的对比" aria-label="Permalink to “与同类框架的对比”">​</a></h2><p>下面三张表只列差异点，不评价优劣。它们各自解决的问题不同，适合的团队也不同。</p><h3 id="abp-framework" tabindex="-1">ABP Framework <a class="header-anchor" href="#abp-framework" aria-label="Permalink to “ABP Framework”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>ABP</th><th>XiHan</th></tr></thead><tbody><tr><td>模块化</td><td>强制模块系统，<code>[DependsOn]</code> 加生命周期钩子</td><td>能力包是可选组织方式，<code>IFeature</code> 加 <code>UseFeature&lt;T&gt;()</code> 显式组合，依赖写在清单里按能力 ID 解析</td></tr><tr><td>实体基类</td><td>继承 <code>Entity&lt;TKey&gt;</code> 等基类</td><td>只提供接口协议（<code>IEntity&lt;TKey&gt;</code>、<code>ISoftDeletable</code>、<code>IMultiTenant</code>），按需组合</td></tr><tr><td>扩展机制</td><td>拦截器加虚方法重写</td><td>固定阶段的管道中间件加源生成器</td></tr><tr><td>动态代理</td><td>运行时代理</td><td>零反射，编译期生成</td></tr><tr><td>包数量</td><td>五十以上</td><td>内核两包（<code>Primitives</code>、<code>Kernel</code>）加按领域的子系统包，三个组合包收口</td></tr><tr><td>依赖注入</td><td>包装 MS DI 加自动注册</td><td>原生 MS DI 加显式注册，生成器登记可选入</td></tr><tr><td>对外暴露</td><td>动态 API（HTTP）</td><td>操作契约，一份契约暴露为 HTTP、gRPC、MCP、命令行</td></tr><tr><td>跨语言</td><td>无</td><td>规范加一致性测试加各语言 SDK</td></tr></tbody></table><h3 id="furion" tabindex="-1">Furion <a class="header-anchor" href="#furion" aria-label="Permalink to “Furion”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>Furion</th><th>XiHan</th></tr></thead><tbody><tr><td>设计理念</td><td>大而全的全家桶，开箱即用</td><td>微内核加可选能力包，按需加载；默认实现保证开箱即用</td></tr><tr><td>依赖注入</td><td>属性扫描自动注册</td><td>显式注册加可选源生成器注册</td></tr><tr><td>动态 API</td><td>内置核心功能</td><td>操作契约加 <code>Protocols.Http</code> 适配器</td></tr><tr><td>配置方式</td><td>约定为主，配置为辅</td><td>显式为主，约定可覆写，二者都有退出机制</td></tr><tr><td>包结构</td><td>单一主包加少量扩展</td><td>抽象包加按机制或技术命名的实现包</td></tr><tr><td>目标场景</td><td>中小型项目快速开发</td><td>中大型、长期维护、需要跨团队共识的项目</td></tr></tbody></table><h3 id="masa-framework" tabindex="-1">MASA Framework <a class="header-anchor" href="#masa-framework" aria-label="Permalink to “MASA Framework”">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>MASA</th><th>XiHan</th></tr></thead><tbody><tr><td>设计理念</td><td>云原生、微服务优先</td><td>部署形态中立，应用清单一键产出容器与 Kubernetes 产物</td></tr><tr><td>模块化</td><td>Building Blocks</td><td>能力图谱加管道阶段</td></tr><tr><td>数据访问</td><td>多 ORM</td><td><code>Persistence.Abstractions</code> 加 EF Core 与 SqlSugar 两个 Provider</td></tr><tr><td>可观测性</td><td>集成 OpenTelemetry</td><td>内核直接基于 <code>System.Diagnostics</code>，<code>Observability.OpenTelemetry</code> 只配导出器</td></tr><tr><td>多租户</td><td>内置</td><td><code>MultiTenancy.*</code> 子系统，管道 Tenant 阶段</td></tr></tbody></table><h2 id="换来的代价" tabindex="-1">换来的代价 <a class="header-anchor" href="#换来的代价" aria-label="Permalink to “换来的代价”">​</a></h2><table tabindex="0"><thead><tr><th>代价</th><th>说明</th></tr></thead><tbody><tr><td>写法更显式</td><td>每个特性要写清单；服务、权限、操作、消息处理器都要在 <code>Configure</code> 里显式登记，源生成器的登记也要显式调用</td></tr><tr><td>序列化要源生成</td><td>操作的请求与响应、领域事件的载荷要登记到 <code>JsonSerializerContext</code>；类型没有登记时生成器报 <code>XHG002</code></td></tr><tr><td>失败用 <code>Result</code> 表达</td><td>仓储、缓存、消息等端口返回 <code>Result</code> 而不是抛异常，调用方要处理失败分支</td></tr><tr><td>文案不写在代码里</td><td>面向人的文字以消息键引用，每个键要在十个语言文件里各有一行</td></tr><tr><td>概念更多</td><td>能力 ID、清单、管道阶段、操作契约、协议适配器是新概念，团队需要时间统一认识</td></tr></tbody></table><p>我认为这些代价都是值得的，因为它们换来的是十年尺度上的可维护性。但如果你的项目生命周期只有几个月，这些约束就只是负担。</p><h2 id="当前限制" tabindex="-1">当前限制 <a class="header-anchor" href="#当前限制" aria-label="Permalink to “当前限制”">​</a></h2><ul><li>当前只有预览版，安装要带 <code>--prerelease</code>，见<a href="/getting-started/installation">环境与安装</a>。</li><li>公开面多数标为 <code>Preview</code> 或 <code>Experimental</code>，正式版前仍可能调整。</li><li>框架不提供机器人、消息通知渠道、模板引擎、脚本引擎、搜索引擎、HTTP 客户端封装、网关、SignalR 封装、对象映射，替代做法见<a href="/appendix/faq">常见问题</a>。</li><li>Provider 覆盖面以<a href="/packages/">包参考</a>列出的为准：持久化有 EF Core 与 SqlSugar，没有 MongoDB；远程配置有 Nacos，没有 Apollo 与 Vault；对象存储有文件系统与 S3 兼容服务。</li></ul><h2 id="用最小成本验证" tabindex="-1">用最小成本验证 <a class="header-anchor" href="#用最小成本验证" aria-label="Permalink to “用最小成本验证”">​</a></h2><ol><li>按<a href="/getting-started/first-app">第一个应用</a>写一个操作，确认装配、管道与 Problem Details 的行为。</li><li>运行<a href="/appendix/samples">示例</a>里的 <code>SimpleApp</code>：同一份订单契约同时在 HTTP、gRPC、MCP 上服务，带租户、认证、权限、事务与发件箱，零外部设施。</li><li>把其中一个默认实现换成团队要用的 Provider，确认业务代码不需要改。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="/appendix/philosophy">设计哲学</a>：这些取舍背后的原则</li><li><a href="/getting-started/installation">环境与安装</a>：开始动手</li></ul>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};